Review this change:
```go
func TestSplitHostPort(t *testing.T) {
	cases := []struct {
		name string
		in   string
		host string
		port int
	}{
		{"simple", "example.com:8080", "example.com", 8080},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			h, p, err := SplitHostPort(tc.in)
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if h != tc.host || p != tc.port {
				t.Errorf("got %q/%d, want %q/%d", h, p, tc.host, tc.port)
			}
		})
	}
}
```

